+const productCards = document.querySelectorAll(".product-card");
+const countdownElement = document.getElementById("countdown");
+const yearElement = document.getElementById("year");
+
+if (yearElement) {
+  yearElement.textContent = new Date().getFullYear();
+}
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const selectedFilter = button.dataset.filter;
+
+    filterButtons.forEach((item) => {
+      const isActive = item === button;
+      item.classList.toggle("is-active", isActive);
+      item.setAttribute("aria-pressed", String(isActive));
+    });
+
+    productCards.forEach((card) => {
+      const matches =
+        selectedFilter === "all" || card.dataset.category === selectedFilter;
+      card.classList.toggle("is-hidden", !matches);
+    });
+  });
+});
+
+const getDealDeadline = () => {
+  const deadline = new Date();
+  deadline.setDate(deadline.getDate() + 3);
+  deadline.setHours(23, 59, 59, 999);
+  return deadline;
+};
+
+const deadline = getDealDeadline();
+
+const updateCountdown = () => {
+  if (!countdownElement) {
+    return;
+  }
+
+  const difference = deadline.getTime() - Date.now();
+
+  if (difference <= 0) {
+    countdownElement.textContent = "Offer closed";
+    return;
+  }
+
+  const hours = Math.floor(difference / (1000 * 60 * 60));
+  const minutes = Math.floor((difference % (1000 * 60 * 60)) / (1000 * 60));
+  const seconds = Math.floor((difference % (1000 * 60)) / 1000);
+
+  countdownElement.textContent = `${String(hours).padStart(2, "0")} : ${String(
+    minutes
+  ).padStart(2, "0")} : ${String(seconds).padStart(2, "0")}`;
+};
+
+updateCountdown();
+setInterval(updateCountdown, 1000);
+

